export type ParsedCollectCreatorFeeInstruction<
    TProgram extends string = typeof RAYDIUM_CP_SWAP_PROGRAM_ADDRESS,
    TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
    programAddress: Address<TProgram>;
    accounts: {
        /** Only pool creator can collect fee */
        creator: TAccountMetas[0];
        authority: TAccountMetas[1];
        /** Pool state stores accumulated protocol fee amount */
        poolState: TAccountMetas[2];
        /** Amm config account stores fund_owner */
        ammConfig: TAccountMetas[3];
        /** The address that holds pool tokens for token_0 */
        token0Vault: TAccountMetas[4];
        /** The address that holds pool tokens for token_1 */
        token1Vault: TAccountMetas[5];
        /** The mint of token_0 vault */
        vault0Mint: TAccountMetas[6];
        /** The mint of token_1 vault */
        vault1Mint: TAccountMetas[7];
        /** The address that receives the collected token_0 fund fees */
        creatorToken0: TAccountMetas[8];
        /** The address that receives the collected token_1 fund fees */
        creatorToken1: TAccountMetas[9];
        /** Spl token program or token program 2022 */
        token0Program: TAccountMetas[10];
        /** Spl token program or token program 2022 */
        token1Program: TAccountMetas[11];
        /** Program to create an ATA for receiving position NFT */
        associatedTokenProgram: TAccountMetas[12];
        /** To create a new program account */
        systemProgram: TAccountMetas[13];
    };
    data: CollectCreatorFeeInstructionData;
};

export function parseCollectCreatorFeeInstruction<
    TProgram extends string,
    TAccountMetas extends readonly AccountMeta[],
>(
    instruction: Instruction<TProgram> &
        InstructionWithAccounts<TAccountMetas> &
        InstructionWithData<ReadonlyUint8Array>,
): ParsedCollectCreatorFeeInstruction<TProgram, TAccountMetas> {
    if (instruction.accounts.length < 14) {
        throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
            actualAccountMetas: instruction.accounts.length,
            expectedAccountMetas: 14,
        });
    }
    let accountIndex = 0;
    const getNextAccount = () => {
        const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
        accountIndex += 1;
        return accountMeta;
    };
    return {
        programAddress: instruction.programAddress,
        accounts: {
            creator: getNextAccount(),
            authority: getNextAccount(),
            poolState: getNextAccount(),
            ammConfig: getNextAccount(),
            token0Vault: getNextAccount(),
            token1Vault: getNextAccount(),
            vault0Mint: getNextAccount(),
            vault1Mint: getNextAccount(),
            creatorToken0: getNextAccount(),
            creatorToken1: getNextAccount(),
            token0Program: getNextAccount(),
            token1Program: getNextAccount(),
            associatedTokenProgram: getNextAccount(),
            systemProgram: getNextAccount(),
        },
        data: getCollectCreatorFeeInstructionDataDecoder().decode(instruction.data),
    };
}
